on class="btn btn-primary"><i class="fas fa-save me-2"></i>Simpan</button></div></form></div></div>
<script>
const phaseByYear=Object.fromEntries([...document.querySelectorAll('#docYear option[data-fase]')].map(o=>[o.value,o.dataset.fase]));
document.getElementById('docYear').addEventListener('change',e=>{if(phaseByYear[e.target.value])document.getElementById('docPhase').value=phaseByYear[e.target.value]});
function openDocumentModal(){const f=document.getElementById('documentForm');f.reset();f.action='{{ route('perencanaan.dokumen.store') }}';document.getElementById('documentMethod').innerHTML='';document.getElementById('documentModalTitle').textContent='Unggah dokumen';document.getElementById('docFileHelp').textContent='Wajib diisi saat menambah dokumen.';document.getElementById('documentModal').querySelector('[name=file]').required=true;bootstrap.Modal.getOrCreateInstance(document.getElementById('documentModal')).show()}
function editDocument(d){const f=document.getElementById('documentForm');f.reset();f.action='{{ url('/perencanaan/dokumen') }}/'+d.id;document.getElementById('documentMethod').innerHTML='<input type="hidden" name="_method" value="PUT">';f.elements.judul.value=d.judul;f.elements.keterangan.value=d.keterangan||'';f.elements.tahun_anggaran_id.value=d.tahun_anggaran_id;f.elements.fase_id.value=d.fase_id;f.elements.file.required=false;document.getElementById('documentModalTitle').textContent='Edit dokumen';document.getElementById('docFileHelp').textContent='Kosongkan jika berkas tidak diganti.';bootstrap.Modal.getOrCreateInstance(document.getElementById('documentModal')).show()}
document.querySelectorAll('.edit-document').forEach(button=>button.addEventListener('click',()=>editDocument(JSON.parse(button.dataset.document))));
</script>
